             "ead": 500.0, "maturity": 5.0},
            {"id": "f-3", "counterparty_id": "cp-b", "lgd": 0.0,
             "ead": 250.0, "maturity": 1.0},
        ],
    }
    body.update(overrides)
    return json.dumps(body).encode("utf-8")


